const update = $json;
const msg =
  update.message ||
  update.channel_post ||
  update.edited_message ||
  update.edited_channel_post ||
  null;

const now = new Date();
const fallbackId = `unknown:${now.getTime()}`;

if (!msg) {
  return {
    json: {
      original_text: '',
      working_text: '',
      chat_id: null,
      message_id: null,
      message_thread_id: null,
      from_user_id: null,
      reply_to_message_id: null,
      source_type: 'unknown',
      quality_ok: false,
      quality_reason: 'no_telegram_message',
      request_id: fallbackId,
      session_key: fallbackId,
      input_stats: {
        characters: 0,
        non_whitespace: 0,
        letters: 0,
        numbers: 0,
        urls: 0,
        lines: 0
      },
      clarification_context: {
        allowed: false,
        round: 0,
        pending_found: false,
        pending_request_id: null,
        questions: [],
        answers: []
      }
    }
  };
}

const text = String(msg.text ?? msg.caption ?? '')
  .replace(/�/g, '')
  .trim();

const nonWhitespace = (text.match(/\S/gu) || []).length;
const letters = (text.match(/\p{L}|\p{M}/gu) || []).length;
const numbers = (text.match(/\p{N}/gu) || []).length;
const urls = (text.match(/(?:https?:\/\/|www\.)\S+/giu) || []).length;
const lines = text ? text.split(/\r?\n/u).length : 0;
const codeLike =
  /[{}\[\]();=<>]/u.test(text) ||
  /``|`[^`]+`/u.test(text);

const isPureCommand =
  /^\/[A-Za-z0-9_]+(?:@[A-Za-z0-9_]+)?\s*$/u.test(text);

const hasInterpretableSignal =
  letters > 0 ||
  numbers > 0 ||
  urls > 0 ||
  codeLike;

let qualityOk =
  Boolean(text) &&
  !isPureCommand &&
  hasInterpretableSignal;

let qualityReason = 'usable_request_content';
if (!text) qualityReason = 'empty_text_or_unsupported_non_text';
else if (isPureCommand) qualityReason = 'bot_command_only';
else if (!hasInterpretableSignal) qualityReason = 'no_interpretable_request_content';

const sourceType = msg.text
  ? 'telegram_text'
  : msg.caption
    ? 'telegram_caption'
    : msg.voice
      ? 'telegram_voice_without_transcript'
      : msg.audio
        ? 'telegram_audio_without_transcript'
        : 'telegram_non_text';

const chatId = msg.chat?.id ?? null;
const messageId = msg.message_id ?? null;
const fromUserId = msg.from?.id ?? null;
const threadId = msg.message_thread_id ?? null;
const replyToMessageId = msg.reply_to_message?.message_id ?? null;

if (chatId === null) {
  qualityOk = false;
  qualityReason = 'missing_chat_id';
}

const requestId = `${chatId ?? 'nochat'}:${messageId ?? now.getTime()}`;
const sessionKey = [
  String(chatId ?? 'nochat'),
  String(fromUserId ?? 'nouser'),
  String(threadId ?? 'nothread')
].join(':');

const clarificationAllowed =
  fromUserId !== null &&
  (sourceType === 'telegram_text' || sourceType === 'telegram_caption');

return {
  json: {
    original_text: text,
    working_text: text,
    chat_id: chatId,
    message_id: messageId,
    message_thread_id: threadId,
    from_user_id: fromUserId,
    reply_to_message_id: replyToMessageId,
    source_type: sourceType,
    quality_ok: qualityOk,
    quality_reason: qualityReason,
    request_id: requestId,
    session_key: sessionKey,
    input_stats: {
      characters: text.length,
      non_whitespace: nonWhitespace,
      letters,
      numbers,
      urls,
      lines
    },
    clarification_context: {
      allowed: clarificationAllowed,
      round: 0,
      pending_found: false,
      pending_request_id: null,
      questions: [],
      answers: []
    }
  }
};

const incoming = $('Input Contract / Session Key').item.json;
const candidate = $json && $json.session_key ? $json : null;

let pending = null;
let stale = false;

if (candidate?.status === 'pending') {
  const expiryMs = Date.parse(String(candidate.expires_at || ''));
  stale = Number.isFinite(expiryMs) ? expiryMs <= Date.now() : true;
  if (!stale) pending = candidate;
}

let route = 'new_request';
if (pending) {
  route = String(pending.request_id) === String(incoming.request_id)
    ? 'duplicate_pending'
    : 'pending_candidate';
}

return {
  json: {
    ...incoming,
    route,
    pending_row: pending,
    clarification_context: {
      ...incoming.clarification_context,
      round: pending ? 1 : 0,
      pending_found: Boolean(pending),
      pending_request_id: pending?.request_id ?? null
    }
  }
};

