function extract(resp) {
  const parts = [];
  for (const item of (Array.isArray(resp?.output) ? resp.output : [])) {
    for (const c of (Array.isArray(item?.content) ? item.content : [])) {
      if (
        typeof c?.text === 'string' &&
        (c.type === 'output_text' || c.type === 'text')
      ) parts.push(c.text);
    }
  }
  return parts.join('\n').trim();
}

function parseJsonLoose(value) {
  if (!value) return null;
  let text = String(value).trim();
  if (/^``/u.test(text) && /`$/u.test(text)) {
    text = text
      .replace(/^`[^\n]*\n?/u, '')
      .replace(/\s*`$/u, '')
      .trim();
  }
  try { return JSON.parse(text); } catch {}
  const first = text.indexOf('{');
  const last = text.lastIndexOf('}');
  if (first >= 0 && last > first) {
    try { return JSON.parse(text.slice(first, last + 1)); } catch {}
  }
  return null;
}

const base = $('Session Router').item.json;
const raw = extract($json);
const parsed = parseJsonLoose(raw);

return {
  json: {
    ...base,
    clarification_router_raw: raw,
    clarification_is_answer: parsed?.is_answer === true
  }
};

const base = $('Answer Context').item.json;
const row = base.pending_row || {};

let requestMap = {};
let questions = [];
try { requestMap = JSON.parse(String(row.request_map_json || '{}')); } catch {}
try { questions = JSON.parse(String(row.questions_json || '[]')); } catch {}

const answer = String(base.working_text || '').trim();

return {
  json: {
    ...base,
    work_mode: 'resume',
    original_text: String(row.original_text || ''),
    working_text: String(row.original_text || ''),
    request_id: String(row.request_id || base.request_id),
    request_map: requestMap,
    request_map_json: JSON.stringify(requestMap),
    clarification_questions: Array.isArray(questions) ? questions : [],
    clarification_answers: answer ? [answer] : [],
    clarification_context: {
      ...base.clarification_context,
      round: 1,
      pending_found: true,
      pending_request_id: String(row.request_id || ''),
      questions: Array.isArray(questions) ? questions : [],
      answers: answer ? [answer] : []
    }
  }
};

const base = $('Parse Clarification Route').item.json;
return {
  json: {
    ...base,
    work_mode: 'new',
    route: 'new_request',
    pending_row: null,
    request_map: null,
    request_map_json: '',
    clarification_questions: [],
    clarification_answers: [],
    clarification_context: {
      ...base.clarification_context,
      round: 0,
      pending_found: false,
      pending_request_id: null,
      questions: [],
      answers: []
    }
  }
};

return {
