if (!map || typeof map !== 'object' || Array.isArray(map)) map = fallback;

const arrayFields = [
  'facts',
  'constraints',
  'preferences',
  'invariants',
  'entities_tokens',
  'exclusions',
  'output_characteristics',
  'success_criteria',
  'dependencies',
  'ambiguities',
  'organizational_inferences',
  'safe_assumptions',
  'unsafe_assumptions'
];

for (const key of arrayFields) {
  if (!Array.isArray(map[key])) map[key] = [];
