  ? x.clarification_questions.slice(0, 2)
  : [];

const now = new Date();
const expires = new Date(now.getTime() + 30 * 60 * 1000);

let clarificationMessage = '';
if (questions.length === 1) {
  clarificationMessage =
    `Нақтырақ сұрау құрастыру үшін бір нәрсені анықтап алайын:\n\n${questions[0]}`;
} else {
  clarificationMessage =
    `Екі нәрсе нәтижеге қатты әсер етеді:\n\n1. ${questions[0]}\n2. ${questions[1]}`;
}

return {
  json: {
    ...x,
    state_row: {
      session_key: String(x.session_key),
      request_id: String(x.request_id),
      chat_id: String(x.chat_id ?? ''),
      from_user_id: String(x.from_user_id ?? ''),
