      status: 'pending',
      created_at: now.toISOString(),
      updated_at: now.toISOString(),
      expires_at: expires.toISOString()
    },
    clarification_message: clarificationMessage
  }
};

const x = $json;
let requestMap = x.request_map;
if (!requestMap || typeof requestMap !== 'object') {
  try { requestMap = JSON.parse(String(x.request_map_json || '{}')); }
  catch { requestMap = {}; }
}

return {
  json: {
    ...x,
    request_map: requestMap,
    request_map_json: JSON.stringify(requestMap),
    clarification_questions: Array.isArray(x.clarification_questions)
      ? x.clarification_questions
